mapper.select:
SELECT * FROM review 
WHERE rv_me_num = #{me_num} 
AND rv_number = #{rv_num}
AND rv_table_name = #{tableName}

mapper.update:
UPDATE review 
SET 
    rv_rating = #{rv_rating},
    rv_content = #{rv_content},
    rv_date = NOW()
WHERE 
    rv_me_num = #{rv_me_num}
    AND rv_table_name = #{rv_table_name}
    AND rv_number = #{rv_number}

mapper.delete:
DELETE FROM review
WHERE rv_number = #{rv_num}
and rv_me_num = #{me_num}
